`,e.jsxs(i.p,{children:["Use ",e.jsx(i.code,{children:"jj log -r .."}),". The ",e.jsx(i.code,{children:".."})," ",e.jsx(i.a,{href:"/reference/revsets#operators",children:"operator"})," lists all visible commits in the repo, excluding the root (which is never interesting and is shared by all repos)."]}),`
